#include "gpu_matvec_warp.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{for(int rows:{128,512,1024,16384}){int cols=512;Vec a(size_t(rows)*cols),x(cols);for(size_t i=0;i<a.size();++i)a[i]=float(int(i%31)-15)/31;for(int i=0;i<cols;++i)x[i]=float(i%17)/17;Device w(a),v(x),ref(rows),out(rows);cudaEvent_t s,e;check(cudaEventCreate(&s));check(cudaEventCreate(&e));float ms[2];for(int path=0;path<2;++path){check(cudaEventRecord(s));for(int i=0;i<20;++i){if(path)ds_matvec_warp<<<(rows+3)/4,128>>>(w.p,v.p,out.p,rows,cols);else matvec<<<(rows+127)/128,128>>>(w.p,v.p,ref.p,rows,cols);}check(cudaEventRecord(e));check(cudaEventSynchronize(e));check(cudaEventElapsedTime(&ms[path],s,e));}auto r=ref.host(),o=out.host();float err=0;for(int i=0;i<rows;++i){if(!std::isfinite(o[i]))return 2;err=std::max(err,std::abs(r[i]-o[i]));}printf("rows=%d cols=%d reference_ms=%.6f warp_ms=%.6f maxerr=%.9g repeats20\n",rows,cols,ms[0],ms[1],err);cudaEventDestroy(s);cudaEventDestroy(e);if(err>1e-4)return 1;}return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 3;}}
